skills.card:
addDuration — Move a date forward or back by days, weeks, months or years.
  needs: from: string, amount: integer, unit: string
  e.g. "what date is 90 days after 2026-07-12" → {"from":"2026-07-12","amount":90,"unit":"days"}

countdownTo — Count how long until a date, or how long since one, from today. Takes the one date.
  needs: to: string
  e.g. "how many days till my sister's wedding on nov 14" → {"to":"2026-11-14"}

currentTime — Today's date and the current time, in your own time zone.
  optional: zone: string
  e.g. "what is the date today" → {}

dayOfWeek — Name the weekday a date lands on — a Monday, a Saturday.
  needs: date: string
  e.g. "what day of the week is 14 November 2026" → {"date":"2026-11-14"}

dayOfYear — Which numbered day of the year a date is, and how much of the year is left.
  needs: date: string
  e.g. "what day of the year is 2026-11-14" → {"date":"2026-11-14"}

daysInMonth — Say how many days long a given month is.
  needs: month: integer, year: integer
  e.g. "how many days in february 2026" → {"month":2,"year":2026}

formatDate — Rewrite a date in a layout you choose, like DD/MM/YYYY or "D MMMM YYYY".
  needs: date: string, format: string
  e.g. "format 2026-11-14 as DD/MM/YYYY" → {"date":"2026-11-14","format":"DD/MM/YYYY"}

isLeapYear — Say whether a year is a leap year, and how many days it has.
  needs: year: integer
  e.g. "is 2026 a leap year" → {"year":2026}

isWeekend — Say whether a date is a weekend or a working day.
  needs: date: string
  e.g. "is 2026-11-14 a weekend" → {"date":"2026-11-14"}

isoWeek — Number the week of the year a date sits in, and when that week begins.
  needs: date: string
  e.g. "what iso week is 2026-11-14" → {"date":"2026-11-14"}

parseDate — Read a messy date — "14 nov", "3/4/2026", "next Tuesday" is a different skill — and return it as an ISO date.
  needs: text: string
  e.g. "what is 14 nov as a date" → {"text":"14 nov"}

parseDuration — Read "2h 15m" or "2 days 4 hours" and give the total in seconds.
  needs: text: string
  e.g. "how many seconds is 1h 30m" → {"text":"1h 30m"}

parseRelativeDate — Turn a relative date like "next Tuesday", "in 3 weeks" or "a month ago" into a real date.
  needs: phrase: string
  e.g. "what date is next tuesday" → {"phrase":"next tuesday"}

timeAgo — Say how long ago a date was, or how far off it is, in plain words like "3 days ago".
  needs: date: string
  e.g. "how long ago was 2026-08-29" → {"date":"2026-08-29"}

